import React from 'react';

const GradesPage = () => {
  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">Grades</h1>
      <div className="bg-white p-6 rounded-lg shadow-md">
        <p className="text-gray-600">Grades page coming soon...</p>
      </div>
    </div>
  );
};

export default GradesPage;
